      "passages": [
        {
          "citaat": "Uitzondering die de toezichthouder laat vervallen zodra hij voortzetting onwenselijk vindt.",
          "functie": "Uitzonderingstype beschreven door het vervalkenmerk bij een negatief voortzettingsoordeel."
        }
      ],
      "gronden": [
        {
          "veld": "bron",
          "bron_id": "B1",
          "citaat": "Herroepbare uitzondering: uitzondering die de toezichthouder laat vervallen zodra hij voortzetting onwenselijk vindt. Een vaste uitzondering heeft dat kenmerk niet. Het register vermeldt bij iedere verleende uitzondering een van beide typen."
        },
        {
          "veld": "bron",
          "bron_id": "B2",
          "citaat": "De toezichthouder weegt of voortzetting van een herroepbare uitzondering wenselijk is en laat de uitzondering vervallen zodra hij voortzetting onwenselijk vindt."
        }
      ],
      "motivering": "De verwijzing is hersteld: dat kenmerk verwijst naar het direct voorafgaande vervalkenmerk. Mijn voorstel blijft pass. B1 onderscheidt daarmee twee typen verleende uitzonderingen; de gehele kern beschrijft het onderscheidende kenmerk. B2 regelt daarnaast de weging en uitvoering. De kern draagt die afweging niet zelfstandig op. De verwijzingswijziging verduidelijkt de bron, maar bewijst op zichzelf deze functie niet.",
      "vraag": null,
      "zekerheid": "hoog",
      "afstand_ontwerp": {
        "oordeel": "zelfstandig",
        "nabije_casus_ids": ["C83", "C30"],
        "motivering": "Het concrete contrast tussen vaste en herroepbare verleende uitzonderingen ondersteunt het vervalkenmerk als typeonderscheid. Die functiegrond verschilt van een los discretionair handelingsvoorbeeld."
      },
      "redundantie_met": [],
      "geschiktheid": "bruikbaar",
      "opmerkingen": [
        "Voorstel, familie, zekerheid en geschiktheid blijven gelijk aan mijn beoordeling van v2.",
        "Een afzonderlijk voorbehoud bij verlening wordt niet als extra bronpremisse ingelezen. De actuele grond is het beschreven vervalkenmerk en het ontbreken daarvan bij vaste uitzonderingen.",
        "Geen resterende concrete bronfout of nieuwe betekenisverschuiving door deze wijziging vastgesteld. De citaten zijn exact en uniek gecontroleerd."
      ]
    }
  ],
